    AddStringRec(NR_WizardFormMainInfo, QStringLiteral("WizardForm"), QStringLiteral("MainInfo"), QStringLiteral("Information about the D-Fend Reborn file structure"));
    AddStringRec(NR_WizardFormMainInfo1, QStringLiteral("WizardForm"), QStringLiteral("MainInfoPart1"), QStringLiteral("D-Fend Reborn is 100% Windows Vista and 7 compatible. This means it respects the conect of dividing the program data into program files and user data. If you have installed D-Fend Reborn in \"user profile mode\", ") + QStringLiteral("the program files are located in the program files folder (\"C:\\Program files\\D-Fend Reborn\" by default) and the user data files are located in a subfolder of the user profile directory (\"C:\\Users\\<you>\\D-Fend Reborn\" by default). ") + QStringLiteral("When D-Fend Reborn is running it is not writing to the program folder any more. All setup data is stored in the user profile subfolder."));
    AddStringRec(NR_WizardFormMainInfo2, QStringLiteral("WizardForm"), QStringLiteral("MainInfoPart2"), QStringLiteral("DOSBox and Windows do not use the same directory sturctures. The programs inside DOSBox only see a subset of the whole Windows directory sturcture. So games running in DOSBox cannot damage your system files ") + QStringLiteral("(unless you setup DOSBox to use your real \"C:\\\" as drive C: in DOSBox). In most cases you want to mount a folder like \"C:\\OldGames\" as drive C: in DOSBox. ") + QStringLiteral("This means if you store a game in \"C:\\OldGames\\Somegame\" you can access this game in DOSBox via \"C:\\Somegame\". But you do not need to worry about mounting drives at all because D-Fend Reborn is mounting the right folders automatically for you."));
    AddStringRec(NR_WizardFormMainInfo3, QStringLiteral("WizardForm"), QStringLiteral("MainInfoPart3"), QStringLiteral("You can store your game where ever you want. But it is recommended to use the predefined games directory (\"C:\\Users\\<you>\\D-Fend Reborn\\VirtualHD\"). If you use this directory for your games, ") + QStringLiteral("D-Fend Reborn can use relative paths in the profile (\".\\VirtualHD\\NewGame\" instead of \"C:\\Users\\<you>\\D-Fend Reborn\\VirtualHD\\NewGame\"). If D-Fend Reborn knows where the games files are located relatively to the program data directory, ") + QStringLiteral("it can transfer the games files to another installation or can make installer packages for you. With absolute pathes this isn't possible."));
